3027	// getStagedFiles returns a list of files staged for commit using native git CLI.
3028	// This is much faster than go-git's worktree.Status() which scans the entire
3029	// working tree. `git diff --cached --raw` uses native git's optimized index
3030	// and filesystem monitors.
3031	//
3032	// Submodule gitlinks (mode 160000 on the staged side, or on the HEAD side of a
3033	// staged removal) are skipped: a submodule pointer is not a file of the
3034	// session's work, and treating one as a staged new file would stamp a trailer
3035	// no condensation can claim. A rename or copy reports its new path, as
3036	// `--name-only` did.
3037	//
3038	// Returns (non-nil empty slice, nil) when no files are staged — callers can
3039	// distinguish "no staged files" from "error resolving staged files" (nil, err).
3040	func getStagedFiles(ctx context.Context) ([]string, error) {
3041		changes, err := getStagedChanges(ctx)
3042		if err != nil {
3043			return nil, err
3044		}
