3059	// getStagedChanges reads staged paths and their blobs in one query. It keeps
3060	// the hook's GIT_INDEX_FILE: `git commit -a` and path-limited commits prepare
3061	// the commit in a temporary index, which the ordinary index does not match.
3062	func getStagedChanges(ctx context.Context) ([]stagedChange, error) {
3063		repoRoot, err := paths.WorktreeRoot(ctx)
3064		if err != nil {
3065			return nil, fmt.Errorf("resolve worktree root: %w", err)
3066		}
3067	
3068		cmd := exec.CommandContext(ctx, "git", "diff", "--cached", "--raw", "-z", "--no-abbrev")
3069		cmd.Dir = repoRoot
3070		output, err := cmd.Output()
3071		if err != nil {
3072			return nil, fmt.Errorf("git diff --cached: %w", err)
3073		}
3074		return parseStagedRaw(output), nil
3075	}
