3080	// parseStagedRaw parses `git diff --raw -z` output into the staged changes,
3081	// skipping submodule gitlinks. Each record is
3082	// ":<src mode> <dst mode> <src sha> <dst sha> <status>\0<path>\0", with a
3083	// second path for renames and copies (status R or C).
3084	func parseStagedRaw(output []byte) []stagedChange {
3085		staged := []stagedChange{}
3086		fields := bytes.Split(output, []byte{0})
3087		for i := 0; i < len(fields); i++ {
3088			header := string(fields[i])
3089			if !strings.HasPrefix(header, ":") {
3090				continue
3091			}
3092			meta := strings.Fields(strings.TrimPrefix(header, ":"))
3093			if len(meta) < 5 || i+1 >= len(fields) {
3094				break
3095			}
3096			status := meta[4]
3097			path := string(fields[i+1])
3098			i++
3099			if (status[0] == 'R' || status[0] == 'C') && i+1 < len(fields) {
3100				path = string(fields[i+1])
3101				i++
3102			}
3103			srcMode, dstMode := meta[0], meta[1]
3104			if dstMode == gitlinkMode || (status == "D" && srcMode == gitlinkMode) {
3105				continue
3106			}
3107			if path == "" {
3108				continue
3109			}
3110			change := stagedChange{path: filepath.ToSlash(path)}
3111			if status == "D" {
3112				change.deleted = true
3113			} else {
3114				change.blob = plumbing.NewHash(meta[3])
3115			}
