31	// inheritReplacedCommitsTrailers carries checkpoint trailers from commits this
32	// commit re-does. After `git reset` and a new commit, the dropped commits are
33	// the ones the reset left unreachable from every branch and remote (see
34	// replacedCommits). A dropped commit is inherited when every file it changed
35	// that is staged now has exactly the content it had before the reset: the work
36	// is recommitted, not rewritten, and one coincidentally identical file among
37	// rewritten ones is not a redo. Returns the inherited IDs, nil when nothing
38	// applies.
39	func (s *ManualCommitStrategy) inheritReplacedCommitsTrailers(ctx context.Context, repo *git.Repository, commitMsgFile, source string) []id.CheckpointID {
40		logCtx := logging.WithComponent(ctx, "checkpoint")
41		logging.Debug(logCtx, "prepare-commit-msg: checking for redone commits")
42		tip, replaced, why := replacedCommits(ctx, repo)
43		if len(replaced) == 0 {
44			logging.Debug(logCtx, "prepare-commit-msg: no commits being redone", slog.String("reason", why))
45			return nil
46		}
47		staged, err := stagedBlobs(ctx)
48		if err != nil || len(staged) == 0 {
49			logging.Debug(logCtx, "prepare-commit-msg: redo check has no staged blobs to compare",
50				slog.Int("replaced_commits", len(replaced)), slog.Any("error", err))
51			return nil
52		}
53		tipTree, err := tip.Tree()
54		if err != nil {
55			return nil
56		}
57		var inherited []id.CheckpointID
58		seen := make(map[id.CheckpointID]bool)
59		for i := len(replaced) - 1; i >= 0; i-- { // oldest first, like a squash message
60			if !recommitsFilesOf(replaced[i], tipTree, staged) {
61				continue
62			}
63			for _, cpID := range trailers.ParseAllCheckpoints(replaced[i].Message) {
64				if !seen[cpID] {
65					seen[cpID] = true
66					inherited = append(inherited, cpID)
67				}
68			}
69		}
70		inherited = withoutDeletedCheckpoints(ctx, inherited)
71		if len(inherited) == 0 {
72			logging.Debug(logCtx, "prepare-commit-msg: redone commits carry no matching trailers",
73				slog.Int("replaced_commits", len(replaced)), slog.Int("staged", len(staged)))
74			return nil
75		}
76		content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
77		if err != nil {
78			return nil
79		}
80		message := string(content)
81		present := make(map[id.CheckpointID]bool)
82		for _, cpID := range trailers.ParseAllCheckpoints(message) {
83			present[cpID] = true
84		}
85		added := 0
86		for _, cpID := range inherited {
87			if !present[cpID] {
88				message = addInheritedCheckpointTrailer(message, cpID, source)
89				added++
90			}
91		}
92		if added > 0 {
93			if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil { //nolint:gosec // path from git hook arg
94				return nil
95			}
96		}
97		logging.Info(logCtx, "prepare-commit-msg: inherited checkpoint trailers from the commits being redone",
98			slog.Int("replaced_commits", len(replaced)),
99			slog.Int("inherited", len(inherited)),
100			slog.Int("added", added))
101		return inherited
102	}
