104	// withRedoneTrailers adds the trailers of the commits this one redoes to the
105	// message and to inherited, and records the combined set for post-commit.
106	func (s *ManualCommitStrategy) withRedoneTrailers(ctx context.Context, repo *git.Repository, commitMsgFile, source string, inherited []id.CheckpointID) []id.CheckpointID {
107		redone := s.inheritReplacedCommitsTrailers(ctx, repo, commitMsgFile, source)
108		if len(redone) == 0 {
109			return inherited
110		}
111		inherited = append(inherited, redone...)
112		recordInheritedTrailers(ctx, inherited)
113		return inherited
