116	// prepareAmendCommitMsg keeps or restores the amended commit's own trailer and
117	// folds in a reset-dropped commit's trailers: `git reset --soft HEAD~1 && git
118	// commit --amend` squashes the last two commits, and the amended commit carries
119	// the work of both.
120	func (s *ManualCommitStrategy) prepareAmendCommitMsg(ctx context.Context, commitMsgFile string, strippedDeleted bool) error {
121		if err := s.handleAmendCommitMsg(ctx, commitMsgFile, strippedDeleted); err != nil {
122			return err
123		}
124		repo, err := OpenRepository(ctx)
125		if err != nil {
126			return nil // the amend itself is prepared; folding is best-effort
127		}
128		defer repo.Close()
129		recordInheritedTrailers(ctx, s.inheritReplacedCommitsTrailers(ctx, repo, commitMsgFile, "commit"))
