133	// replacedCommits finds the commits the latest reset dropped: the tip HEAD left
134	// and the commits reachable from it that no branch, remote or HEAD still
135	// reaches. The reset is read from HEAD's reflog rather than ORIG_HEAD, which a
136	// later `git reset` to HEAD or `git stash` overwrites. Walking back from the
137	// newest entry, resets that did not move HEAD (unstaging, stash) are skipped,
138	// and commits made since count only while each of them redoes some of the
139	// dropped work; any other ref operation (checkout, merge, rebase, pull) means
140	// there is no redo in progress.
141	func replacedCommits(ctx context.Context, repo *git.Repository) (*object.Commit, []*object.Commit, string) {
142		var since []plumbing.Hash
143		var tipHash plumbing.Hash
144		for _, e := range headReflog(ctx) {
145			switch {
146			case strings.HasPrefix(e.msg, "commit"):
147				since = append(since, e.newHash)
148				continue
149			case strings.HasPrefix(e.msg, "reset:") && e.oldHash == e.newHash:
150				continue // unstaging or a stash: HEAD did not move
151			case strings.HasPrefix(e.msg, "reset:"):
152				tipHash = e.oldHash
153			default:
154				return nil, nil, "the latest ref operation was not a reset"
155			}
156			break
157		}
158		if tipHash.IsZero() {
159			return nil, nil, "no reset in HEAD's reflog"
160		}
161		tip, err := repo.CommitObject(tipHash)
162		if err != nil {
163			return nil, nil, "the reset's old HEAD is not a commit"
164		}
165		tipTree, err := tip.Tree()
166		if err != nil {
167			return nil, nil, "the reset's old HEAD has no tree"
168		}
169		// A commit since the reset that recommitted nothing at the old HEAD's
170		// content cannot have redone dropped work. Checked first, newest first,
171		// because it is the usual answer for every ordinary commit after a reset
172		// and it needs no subprocess or walk of the dropped commits.
173		sinceCommits := make([]*object.Commit, 0, len(since))
174		for _, h := range since {
175			c, err := repo.CommitObject(h)
176			if err != nil || !redoesDroppedWork(c, nil, tipTree) {
177				return nil, nil, "a commit since the reset redid none of the dropped work"
178			}
179			sinceCommits = append(sinceCommits, c)
180		}
181		dropped := unreachableCommits(ctx, repo, tipHash)
182		if len(dropped) == 0 {
183			return nil, nil, "the reset dropped nothing a branch does not still reach"
184		}
185		changed := changedPaths(dropped)
186		for _, c := range sinceCommits {
187			if !redoesDroppedWork(c, changed, tipTree) {
188				return nil, nil, "a commit since the reset redid none of the dropped work"
189			}
190		}
191		return tip, dropped, ""
192	}
