194	type reflogEntry struct {
195		oldHash, newHash plumbing.Hash
196		msg              string
197	}
198	
199	// maxReflogBytes bounds how much of HEAD's reflog a commit hook reads, and
200	// maxReflogEntries is the same bound, roughly, for the git fallback.
201	const (
202		maxReflogBytes   = 64 << 10
203		maxReflogEntries = 400
204	)
205	
206	// headReflog returns HEAD's most recent reflog entries, newest first, read
207	// from the per-worktree logs/HEAD so each entry carries the old and new HEAD.
208	func headReflog(ctx context.Context) []reflogEntry {
209		root, err := perWorktreeGitRoot(ctx)
210		if err != nil {
211			return nil
212		}
213		f, err := osroot.OpenNoFollow(root, "logs/HEAD")
214		if errors.Is(err, fs.ErrNotExist) {
215			// The reftable backend keeps reflogs in .git/reftable/, which only
216			// git reads; the files backend just has none yet.
217			return headReflogFromGit(ctx)
218		}
219		if err != nil {
220			return nil
221		}
222		defer f.Close()
223		info, err := f.Stat()
224		if err != nil {
225			return nil
226		}
227		offset := max(info.Size()-maxReflogBytes, 0)
228		data := make([]byte, info.Size()-offset)
229		if _, err := f.ReadAt(data, offset); err != nil && !errors.Is(err, io.EOF) {
230			return nil
231		}
232		lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
233		if offset > 0 && len(lines) > 0 {
234			lines = lines[1:] // the first line may be cut
235		}
236		var out []reflogEntry
237		for i := len(lines) - 1; i >= 0; i-- {
238			head, msg, ok := strings.Cut(lines[i], "\t")
239			fields := strings.Fields(head)
240			if !ok || len(fields) < 2 || !plumbing.IsHash(fields[0]) || !plumbing.IsHash(fields[1]) {
241				continue
242			}
243			out = append(out, reflogEntry{oldHash: plumbing.NewHash(fields[0]), newHash: plumbing.NewHash(fields[1]), msg: msg})
244		}
245		return out
246	}
247	
248	// headReflogFromGit reads HEAD's reflog through git, for the reftable backend.
249	// git prints only each entry's new HEAD; an entry's old HEAD is the new HEAD of
250	// the entry before it.
251	func headReflogFromGit(ctx context.Context) []reflogEntry {
252		root, err := paths.WorktreeRoot(ctx)
253		if err != nil {
254			return nil
255		}
256		cmd := exec.CommandContext(ctx, "git", "reflog", "show", "-n", strconv.Itoa(maxReflogEntries), "--format=%H%x09%gs", "HEAD")
257		cmd.Dir = root
258		cmd.Env = gitrepo.EnvWithoutRepoOverrides()
259		out, err := cmd.Output()
260		if err != nil {
261			logging.Debug(logging.WithComponent(ctx, "checkpoint"), "prepare-commit-msg: could not read HEAD's reflog",
262				slog.String("error", err.Error()))
263			return nil
264		}
265		var entries []reflogEntry
266		lines := strings.Split(strings.TrimSpace(string(out)), "\n")
267		for i, line := range lines {
268			hash, msg, ok := strings.Cut(line, "\t")
269			if !ok || !plumbing.IsHash(hash) {
270				continue
271			}
272			e := reflogEntry{newHash: plumbing.NewHash(hash), msg: msg}
273			if i+1 < len(lines) {
274				if older, _, ok := strings.Cut(lines[i+1], "\t"); ok && plumbing.IsHash(older) {
275					e.oldHash = plumbing.NewHash(older)
276				}
277			}
278			entries = append(entries, e)
279		}
280		return entries
281	}
