283	// unreachableCommits lists the commits reachable from tip that HEAD, no remote
284	// and no other branch reaches: the work only the reset's old HEAD holds.
285	// Merged-in history and a teammate's commits still on another branch are never
286	// dropped. A branch pointing at tip itself is a backup of the very work being
287	// redone, so it does not count as still reaching it.
288	func unreachableCommits(ctx context.Context, repo *git.Repository, tip plumbing.Hash) []*object.Commit {
289		root, err := paths.WorktreeRoot(ctx)
290		if err != nil {
291			return nil
292		}
293		refsCmd := exec.CommandContext(ctx, "git", "for-each-ref", "--format=%(objectname)", "refs/heads", "refs/remotes")
294		refsCmd.Dir = root
295		refsCmd.Env = gitrepo.EnvWithoutRepoOverrides()
296		refs, err := refsCmd.Output()
297		if err != nil {
298			return nil
299		}
300		var exclude strings.Builder
301		exclude.WriteString("^HEAD\n")
302		for _, ref := range strings.Fields(string(refs)) {
303			if plumbing.IsHash(ref) && ref != tip.String() {
304				exclude.WriteString("^" + ref + "\n")
305			}
306		}
307		cmd := exec.CommandContext(ctx, "git", "rev-list", "--max-count="+strconv.Itoa(maxReplacedCommits), tip.String(), "--stdin")
308		cmd.Dir = root
309		cmd.Env = gitrepo.EnvWithoutRepoOverrides()
310		cmd.Stdin = strings.NewReader(exclude.String())
311		out, err := cmd.Output()
312		if err != nil {
313			return nil
314		}
315		var commits []*object.Commit
316		for _, line := range strings.Fields(string(out)) {
317			if !plumbing.IsHash(line) {
318				continue
319			}
320			if c, err := repo.CommitObject(plumbing.NewHash(line)); err == nil {
321				commits = append(commits, c)
322			}
323		}
324		return commits
325	}
