327	// changedPaths is every path the given commits changed relative to their first
328	// parent.
329	func changedPaths(commits []*object.Commit) map[string]bool {
330		out := make(map[string]bool)
331		for _, c := range commits {
332			changes, err := firstParentChanges(c)
333			if err != nil {
334				continue
335			}
336			for _, change := range changes {
337				for _, p := range []string{change.To.Name, change.From.Name} {
338					if p != "" {
339						out[p] = true
340					}
341				}
