349	// the cheap necessary condition checked before the dropped commits are known.
350	func redoesDroppedWork(c *object.Commit, dropped map[string]bool, tipTree *object.Tree) bool {
351		changes, err := firstParentChanges(c)
352		if err != nil {
353			return false
354		}
