378		tree, err := c.Tree()
379		if err != nil {
380			return nil, err //nolint:wrapcheck // callers only test for nil
381		}
382		parent, err := c.Parents().Next()
383		if err != nil {
384			return nil, err //nolint:wrapcheck // callers only test for nil
385		}
