411	// recommitsFilesOf reports whether c's work is what is staged: at least one
412	// file c changed is staged, and every staged file c changed has the content it
413	// had at the reset's old HEAD (tipTree).
414	func recommitsFilesOf(c *object.Commit, tipTree *object.Tree, staged map[string]stagedEntry) bool {
415		changes, err := firstParentChanges(c)
416		if err != nil {
417			return false
418		}
419		matched := false
420		for _, change := range changes {
421			// A rename can be partially staged as either the destination addition
422			// or the source deletion, so both endpoints can independently prove
423			// that part of the dropped commit is being redone.
424			for _, path := range []string{change.To.Name, change.From.Name} {
425				if path == "" {
426					continue
427				}
428				entry, ok := staged[path]
429				if !ok {
430					continue
431				}
432				tipEntry, absent, err := findTreeEntry(tipTree, path)
433				switch {
434				case err != nil:
435					return false
436				case entry.deleted && absent, !entry.deleted && !absent && tipEntry.Hash.Equal(entry.blob):
437					matched = true
438				default:
439					return false // staged, but rewritten: not this commit's work
440				}
441			}
442		}
443		return matched
444	}
