446	// findTreeEntry distinguishes an absent path from a tree-read failure. Walking
447	// one component at a time also makes a non-directory ancestor an ordinary
448	// absence instead of asking go-git to decode that blob as a tree.
449	func findTreeEntry(tree *object.Tree, path string) (*object.TreeEntry, bool, error) {
450		parts := strings.Split(path, "/")
451		for i, part := range parts {
452			entry, err := tree.FindEntry(part)
453			if errors.Is(err, object.ErrEntryNotFound) {
454				return nil, true, nil
455			}
456			if err != nil {
457				return nil, false, fmt.Errorf("find tree entry %q: %w", part, err)
458			}
459			if i == len(parts)-1 {
460				return entry, false, nil
461			}
462			if entry.Mode != filemode.Dir {
463				return nil, true, nil
464			}
465			tree, err = tree.Tree(part)
466			if err != nil {
467				return nil, false, fmt.Errorf("open tree %q: %w", part, err)
468			}
469		}
470		return nil, true, nil
471	}
