//go:build integration

package integration

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/entireio/cli/cmd/entire/cli/trailers"
)

// Review repro: a dropped commit modified b.txt; the redo deletes b.txt and
// adds c.txt with similar content. b.txt is staged with different content
// than the dropped tip, so the commit is not a redo of that work.
func TestReviewRepro_RenameHidesRewrittenDeletion(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name      string
		configArg []string
	}{
		{name: "default-renames"},
		{name: "no-renames", configArg: []string{"-c", "diff.renames=false"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			env := NewFeatureBranchEnv(t)
			git := gitWithEntireCommitHooks(t, env)
			var lines []string
			for i := 1; i <= 30; i++ {
				lines = append(lines, strings.Repeat("x", i))
			}
			body := strings.Join(lines, "\n") + "\n"
			env.WriteFile("a.txt", "base\n")
			env.WriteFile("b.txt", body)
			git("add", "a.txt", "b.txt")
			git("commit", "--no-gpg-sign", "-m", "base")

			env.WriteFile("a.txt", "agent\n")
			env.WriteFile("b.txt", body+"agent line\n")
			env.GitAdd("a.txt")
			env.GitAdd("b.txt")
			env.GitCommitWithCheckpointID("agent: edit a and b", advForeignCheckpoint)

			git("reset", "-q", "HEAD~1")
			git("add", "a.txt")
			git("rm", "-q", "b.txt")
			env.WriteFile("c.txt", body)
			git("add", "c.txt")
			t.Logf("staged raw:\n%s", strings.ReplaceAll(git(append(tc.configArg, "diff", "--cached", "--raw", "-z")...), "\x00", " | "))
			git(append(tc.configArg, "commit", "--no-gpg-sign", "-m", "redo")...)

			var got []string
			for _, cpID := range trailers.ParseAllCheckpoints(git("log", "-1", "--format=%B")) {
				got = append(got, cpID.String())
			}
			t.Logf("trailers on redo commit: %v", got)
			require.NotContains(t, got, advForeignCheckpoint, "b.txt is staged as deleted, not with the dropped tip's content")
		})
	}
}

